import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps
from hourglass.errors import OutsideHoursError

OPEN = parse_span("09:00-17:00")

def spans(*texts):
    return [parse_span(text) for text in texts]

class FindGapsTests(unittest.TestCase):
    def test_midday_gap(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage(self):
        worked = spans("09:00-13:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_overlaps_count_once(self):
        worked = spans("09:00-12:00", "10:00-14:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 14:00-17:00 (180 min)"]
        )

    def test_edges_and_order(self):
        worked = spans("14:00-15:00", "10:00-11:00")
        self.assertEqual(find_gaps(worked, OPEN), [
            "gap 09:00-10:00 (60 min)",
            "gap 11:00-14:00 (180 min)",
            "gap 15:00-17:00 (120 min)"
        ])

    def test_accepts_iterator(self):
        worked = iter(spans("09:00-16:00"))
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 16:00-17:00 (60 min)"]
        )

class OutsideHoursTests(unittest.TestCase):
    def test_starts_early(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("08:00-12:00"), OPEN)

    def test_ends_late(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("16:00-18:00"), OPEN)

    def test_exact_fit_is_fine(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])

    def test_any_bad_span_raises(self):
        worked = spans("09:00-10:00") + [Span(0, 60)]
        with self.assertRaises(OutsideHoursError):
            find_gaps(worked, OPEN)

if __name__ == "__main__":
    unittest.main()
